    CONSTRAINT fact_prescription_transactions_cost_price_check CHECK ((cost_price >= (0)::numeric)),
    CONSTRAINT fact_prescription_transactions_days_supply_check CHECK ((days_supply > 0)),
    CONSTRAINT fact_prescription_transactions_quantity_dispensed_check CHECK ((quantity_dispensed > 0)),
    CONSTRAINT fact_prescription_transactions_total_amount_check CHECK ((total_amount >= (0)::numeric)),
