    total_amount numeric(12,2) NOT NULL,
    cost_price numeric(10,2),
    profit_margin numeric(12,2) GENERATED ALWAYS AS ((total_amount - COALESCE((cost_price * (quantity_dispensed)::numeric), (0)::numeric))) STORED,
    insurance_coverage_amount numeric(12,2) DEFAULT 0,
