--
-- Name: v_business_kpis; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_business_kpis AS
 SELECT sum(fact_prescription_transactions.total_amount) AS total_revenue,
    sum(fact_prescription_transactions.profit_margin) AS total_profit,
    round(avg(fact_prescription_transactions.total_amount), 2) AS avg_transaction_value,
    count(*) AS total_prescriptions,
    count(DISTINCT fact_prescription_transactions.patient_key) AS unique_patients,
    sum(fact_prescription_transactions.quantity_dispensed) AS total_units_dispensed,
    count(
        CASE
            WHEN ((fact_prescription_transactions.payment_method)::text = 'Medical_Aid'::text) THEN 1
            ELSE NULL::integer
        END) AS medical_aid_count,
    count(
        CASE
            WHEN ((fact_prescription_transactions.payment_method)::text = 'Cash'::text) THEN 1
            ELSE NULL::integer
        END) AS cash_count,
    round((((count(
        CASE
            WHEN ((fact_prescription_transactions.payment_method)::text = 'Medical_Aid'::text) THEN 1
            ELSE NULL::integer
        END))::numeric * 100.0) / (NULLIF(count(*), 0))::numeric), 1) AS medical_aid_pct,
    min(fact_prescription_transactions.prescription_date) AS data_from,
    max(fact_prescription_transactions.prescription_date) AS data_to
   FROM dwh.fact_prescription_transactions;


--
-- Name: v_data_quality_summary; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_data_quality_summary AS
 SELECT data_quality_log.run_date,
    data_quality_log.dataset,
    count(*) AS total_checks,
    sum(data_quality_log.rows_checked) AS total_rows_checked,
    sum(data_quality_log.rows_failed) AS total_rows_failed,
    round((((sum(data_quality_log.rows_failed))::numeric * 100.0) / (NULLIF(sum(data_quality_log.rows_checked), 0))::numeric), 2) AS overall_failure_rate_pct,
    count(
        CASE
            WHEN ((data_quality_log.severity)::text = 'CRITICAL'::text) THEN 1
            ELSE NULL::integer
        END) AS critical_issues,
    count(
        CASE
            WHEN ((data_quality_log.severity)::text = 'WARNING'::text) THEN 1
            ELSE NULL::integer
        END) AS warnings,
    count(
        CASE
            WHEN ((data_quality_log.severity)::text = 'INFO'::text) THEN 1
            ELSE NULL::integer
        END) AS info_items
   FROM dwh.data_quality_log
  GROUP BY data_quality_log.run_date, data_quality_log.dataset
  ORDER BY data_quality_log.run_date DESC, data_quality_log.dataset;


--
-- Name: v_pipeline_daily; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_pipeline_daily AS
 SELECT pipeline_runs.run_date,
    count(*) AS run_count,
    sum(pipeline_runs.rows_loaded) AS rows_loaded,
    sum(pipeline_runs.rows_skipped) AS rows_skipped,
    sum(pipeline_runs.rows_failed) AS rows_failed,
    avg(pipeline_runs.duration_seconds) AS avg_duration_s,
    max(
        CASE
            WHEN ((pipeline_runs.status)::text = 'failed'::text) THEN 1
            ELSE 0
        END) AS had_failure
   FROM dwh.pipeline_runs
  GROUP BY pipeline_runs.run_date
  ORDER BY pipeline_runs.run_date DESC;


--
-- Name: v_pipeline_summary; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_pipeline_summary AS
 SELECT count(*) AS total_runs,
    count(
        CASE
            WHEN ((pipeline_runs.status)::text = 'success'::text) THEN 1
            ELSE NULL::integer
        END) AS successful_runs,
    count(
        CASE
            WHEN ((pipeline_runs.status)::text = 'failed'::text) THEN 1
            ELSE NULL::integer
        END) AS failed_runs,
    count(
        CASE
            WHEN ((pipeline_runs.status)::text = 'partial'::text) THEN 1
            ELSE NULL::integer
        END) AS partial_runs,
    round((((count(
        CASE
            WHEN ((pipeline_runs.status)::text = 'success'::text) THEN 1
            ELSE NULL::integer
        END))::numeric * 100.0) / (NULLIF(count(*), 0))::numeric), 1) AS success_rate_pct,
    sum(pipeline_runs.rows_loaded) AS total_rows_loaded,
    avg(pipeline_runs.duration_seconds) AS avg_duration_seconds,
    max(pipeline_runs.run_date) AS last_run_date,
    max(pipeline_runs.started_at) AS last_run_timestamp
   FROM dwh.pipeline_runs;


--
-- Name: v_quality_trend; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_quality_trend AS
 SELECT data_quality_log.run_date,
    sum(data_quality_log.rows_checked) AS total_rows_checked,
    sum(data_quality_log.rows_passed) AS total_rows_passed,
    sum(data_quality_log.rows_failed) AS total_rows_failed,
    round((((sum(data_quality_log.rows_passed))::numeric * 100.0) / (NULLIF(sum(data_quality_log.rows_checked), 0))::numeric), 2) AS pass_rate_pct,
    count(
        CASE
            WHEN ((data_quality_log.severity)::text = 'CRITICAL'::text) THEN 1
            ELSE NULL::integer
        END) AS critical_count
   FROM dwh.data_quality_log
  GROUP BY data_quality_log.run_date
  ORDER BY data_quality_log.run_date DESC;


--
-- Name: v_revenue_by_pharmacy; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_revenue_by_pharmacy AS
 SELECT ph.location_name,
    ph.demographic_profile,
    count(f.prescription_transaction_key) AS prescription_count,
    sum(f.total_amount) AS total_revenue,
    sum(f.profit_margin) AS total_profit,
    round(avg(f.total_amount), 2) AS avg_transaction,
    round(((sum(f.profit_margin) * 100.0) / NULLIF(sum(f.total_amount), (0)::numeric)), 1) AS profit_margin_pct
   FROM (dwh.fact_prescription_transactions f
     JOIN dwh.dim_pharmacy ph ON ((f.pharmacy_key = ph.pharmacy_key)))
  GROUP BY ph.location_name, ph.demographic_profile
  ORDER BY (sum(f.total_amount)) DESC;


--
-- Name: v_stock_alerts; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_stock_alerts AS
 SELECT ph.location_name,
    m.medication_name,
    m.therapeutic_class,
    f.stock_status_code,
    f.quantity_on_hand,
    f.reorder_point,
    f.stock_value_at_retail,
        CASE
            WHEN ((f.stock_status_code)::text = 'OUT'::text) THEN 1
            WHEN ((f.stock_status_code)::text = 'LOW'::text) THEN 2
            WHEN ((f.stock_status_code)::text = 'NEAR_EXPIRY'::text) THEN 3
            ELSE 4
        END AS urgency_rank
   FROM ((dwh.fact_inventory_snapshots f
     JOIN dwh.dim_pharmacy ph ON ((f.pharmacy_key = ph.pharmacy_key)))
     JOIN dwh.dim_medication m ON ((f.medication_key = m.medication_key)))
  WHERE ((f.snapshot_date_key = ( SELECT max(fact_inventory_snapshots.snapshot_date_key) AS max
           FROM dwh.fact_inventory_snapshots)) AND ((f.stock_status_code)::text = ANY ((ARRAY['OUT'::character varying, 'LOW'::character varying, 'NEAR_EXPIRY'::character varying])::text[])))
  ORDER BY
        CASE
            WHEN ((f.stock_status_code)::text = 'OUT'::text) THEN 1
            WHEN ((f.stock_status_code)::text = 'LOW'::text) THEN 2
            WHEN ((f.stock_status_code)::text = 'NEAR_EXPIRY'::text) THEN 3
            ELSE 4
        END, ph.location_name, m.medication_name;


--
-- Name: v_top_medications; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_top_medications AS
 SELECT m.medication_name,
    m.therapeutic_class,
    c.clinical_category,
    c.movement_class,
    count(f.prescription_transaction_key) AS prescription_count,
    sum(f.quantity_dispensed) AS total_units,
    sum(f.total_amount) AS total_revenue,
    round(avg(f.total_amount), 2) AS avg_revenue_per_rx
   FROM ((dwh.fact_prescription_transactions f
     JOIN dwh.dim_medication m ON ((f.medication_key = m.medication_key)))
     JOIN dwh.dim_medication_category c ON ((m.category_key = c.category_key)))
  GROUP BY m.medication_name, m.therapeutic_class, c.clinical_category, c.movement_class
  ORDER BY (count(f.prescription_transaction_key)) DESC;


--
-- Name: v_warehouse_growth; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_warehouse_growth AS
 SELECT d.full_date AS snapshot_date,
    count(f.prescription_transaction_key) AS prescriptions_on_day,
    sum(count(f.prescription_transaction_key)) OVER (ORDER BY d.full_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_prescriptions,
    sum(f.total_amount) AS daily_revenue,
    sum(sum(f.total_amount)) OVER (ORDER BY d.full_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_revenue
   FROM (dwh.dim_date d
     LEFT JOIN dwh.fact_prescription_transactions f ON ((d.date_key = f.transaction_date_key)))
  WHERE ((d.full_date >= ( SELECT min(fact_prescription_transactions.prescription_date) AS min
           FROM dwh.fact_prescription_transactions)) AND (d.full_date <= CURRENT_DATE))
  GROUP BY d.full_date
  ORDER BY d.full_date;


